using System.Text;

namespace Lotusim.Dataset
{
    public static class DatasetSequenceGallery
    {
        public static string Build(string[] images,int width,int height,int boxes,DatasetSensorSettings settings)
        {
            var h=new StringBuilder("<!doctype html><html lang='fr'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Captures maritimes</title><style>body{background:#14212d;color:#eaf2f8;font:16px system-ui;margin:24px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px}figure{margin:0;background:#203343;border-radius:9px;padding:10px}img{width:100%;display:block}a{color:#91d8ff}button,select{padding:9px;margin:5px;cursor:pointer}dialog{background:#14212d;color:white;width:94vw;max-width:none;height:92vh;border:1px solid #547083}.viewport{height:calc(100% - 60px);overflow:auto}.viewport img{width:auto;max-width:none}.viewport.fit img{width:100%;height:100%;object-fit:contain}small{color:#bdcbd7}header{margin-bottom:18px}</style><h1>Captures maritimes</h1><p>");
            h.Append(images.Length+" instants · "+width+" × "+height+" pixels · "+boxes+" annotations géométriques. Cliquer une image pour zoomer à 100 %.</p><header><label>Mode <select id='mode'><option value='rgb'>RGB</option>");
            if(settings?.thermal==true) h.Append("<option value='thermal'>IR synthétique — non calibré</option>");
            if(settings?.nightVision==true) h.Append("<option value='nightvision'>Vision nocturne simulée</option>");
            h.Append("</select></label><label><input id='annotated' type='checkbox' checked> Annotations</label> · <a href='annotations.coco.json'>COCO RGB</a> · <a href='events.json'>Événements</a>");
            if(settings?.thermal==true) h.Append(" · <a href='annotations.thermal.coco.json'>COCO IR</a>");
            if(settings?.nightVision==true) h.Append(" · <a href='annotations.nightvision.coco.json'>COCO NV</a>");
            h.Append("<p><span style='color:#f04141'>NR : non reconnaissable</span> · <span style='color:#ffc420'>PR : partiellement reconnaissable</span> · <span style='color:#28e664'>R : reconnaissable</span></p><p><small>Pourcentage = pixels visibles / silhouette complète projetée DANS LE CADRE. Eau et objets au premier plan occultent les objets derrière. NR / PR / R : heuristique RGB de taille native, visibilité et contraste, non validée humainement ; ce n'est pas une prédiction IA. La catégorie affichée provient d'Unity. Les statuts RGB sont partagés sur IR / NV sans juger leur reconnaissabilité propre.</small></p><p><a href='recognition-policy.json'>Seuils NR / PR / R</a> · <a href='annotations.recognizable.coco.json'>COCO filtré R uniquement</a> · Agent visuel indépendant : voir son dossier de résultats séparé.</p></header><main>");
            foreach(string id in images) h.Append("<figure data-id='"+id+"'><a class='full' href='overlays/"+id+".png'><img loading='lazy' src='overlays/"+id+".png' alt='"+id+"'></a><p>"+id+" · <a class='raw' href='rgb/"+id+".png'>Image originale</a> · <a href='annotations/"+id+".json'>JSON</a></p></figure>");
            h.Append("</main><dialog id='viewer'><button id='close'>Fermer</button><button id='fit'>Adapter à l'écran</button><button id='actual'>100 % — pixels natifs</button><a id='original' target='_blank' rel='noopener'>Ouvrir l'original</a><div class='viewport'><img alt='Vue en pixels natifs'></div></dialog><script>const mode=document.getElementById('mode'),ann=document.getElementById('annotated'),viewer=document.getElementById('viewer'),viewport=viewer.querySelector('.viewport');function paths(id){const m=mode.value;return {raw:m+'/'+id+'.png',view:(ann.checked?(m==='rgb'?'overlays':'overlays-'+m):m)+'/'+id+'.png'}}function refresh(){document.querySelectorAll('figure').forEach(f=>{const p=paths(f.dataset.id);f.querySelector('img').src=p.view;f.querySelector('.full').href=p.view;f.querySelector('.raw').href=p.raw})}mode.onchange=ann.onchange=refresh;document.querySelectorAll('.full').forEach(a=>a.onclick=e=>{e.preventDefault();viewport.classList.remove('fit');viewer.querySelector('img').src=a.href;document.getElementById('original').href=a.href;viewer.showModal()});document.getElementById('close').onclick=()=>viewer.close();document.getElementById('fit').onclick=()=>viewport.classList.add('fit');document.getElementById('actual').onclick=()=>viewport.classList.remove('fit');</script></html>");
            return h.ToString();
        }
    }
}
